questionvariables.text:
cv3(v) := matrix([v[1]],[v[2]],[v[3]]);
/* Design: sort vectors as same direction, opposite or not parallel; fixed order "same", "opposite", "not", with the correct category's position varying. Each set has a positive multiple, a negative multiple, a near miss and one more. Source: adapted from SMP AS/A2 Core 4, Chapter 9, Exercise C, Q4 and C5. */
plist: [[[-4,6,2],[["same",[-12,18,6]],["same",[-16,24,8]],["opp",[12,-18,-6]],["not",[8,-12,-5]]]],[[-3,-1,5],[["not",[3,-1,-5]],["not",[-7,-2,10]],["opp",[6,2,-10]],["same",[-12,-4,20]]]],[[4,-2,4],[["same",[8,-4,8]],["not",[12,-6,11]],["same",[6,-3,6]],["opp",[-12,6,-12]]]],[[2,-6,4],[["opp",[-2,6,-4]],["not",[6,-18,11]],["same",[3,-9,6]],["not",[2,6,-4]]]],[[-4,1,-5],[["not",[-8,1,-10]],["same",[-16,4,-20]],["same",[-12,3,-15]],["opp",[4,-1,5]]]],[[-3,4,-4],[["opp",[9,-12,12]],["opp",[6,-8,8]],["not",[-6,7,-8]],["same",[-6,8,-8]]]],[[4,-6,-2],[["same",[12,-18,-6]],["opp",[-6,9,3]],["opp",[-2,3,1]],["not",[-9,12,4]]]],[[5,2,-4],[["same",[15,6,-12]],["not",[-5,-2,-4]],["not",[10,3,-8]],["opp",[-15,-6,12]]]],[[2,2,1],[["not",[6,5,3]],["not",[-2,-2,1]],["opp",[-6,-6,-3]],["same",[4,4,2]]]],[[-2,4,-2],[["not",[5,-8,4]],["opp",[6,-12,6]],["same",[-1,2,-1]],["same",[-6,12,-6]]]]];
ix: 1+rand(10);
A: plist[ix][1];
v1: plist[ix][2][1][2]; c1: plist[ix][2][1][1];
sm1: is(c1 = "same"); op1: is(c1 = "opp"); nt1: is(c1 = "not"); pr1: not nt1;
k1: v1[1]/A[1];
rt1: [v1[1]/A[1], v1[2]/A[2], v1[3]/A[3]];
opt1: [["same1", sm1, "parallel, same direction"], ["opp1", op1, "parallel, opposite direction"], ["not1", nt1, "not parallel"]];
ta1: first(mcq_correct(opt1));
/* named error: same and opposite confused; a near miss taken as parallel */
dg1: if sm1 then opt1[2][1] else opt1[1][1];
gw1: if nt1 then opt1[2][1] else opt1[3][1];
v2: plist[ix][2][2][2]; c2: plist[ix][2][2][1];
sm2: is(c2 = "same"); op2: is(c2 = "opp"); nt2: is(c2 = "not"); pr2: not nt2;
k2: v2[1]/A[1];
rt2: [v2[1]/A[1], v2[2]/A[2], v2[3]/A[3]];
opt2: [["same2", sm2, "parallel, same direction"], ["opp2", op2, "parallel, opposite direction"], ["not2", nt2, "not parallel"]];
ta2: first(mcq_correct(opt2));
/* named error: same and opposite confused; a near miss taken as parallel */
dg2: if sm2 then opt2[2][1] else opt2[1][1];
gw2: if nt2 then opt2[2][1] else opt2[3][1];
v3: plist[ix][2][3][2]; c3: plist[ix][2][3][1];
sm3: is(c3 = "same"); op3: is(c3 = "opp"); nt3: is(c3 = "not"); pr3: not nt3;
k3: v3[1]/A[1];
rt3: [v3[1]/A[1], v3[2]/A[2], v3[3]/A[3]];
opt3: [["same3", sm3, "parallel, same direction"], ["opp3", op3, "parallel, opposite direction"], ["not3", nt3, "not parallel"]];
ta3: first(mcq_correct(opt3));
/* named error: same and opposite confused; a near miss taken as parallel */
dg3: if sm3 then opt3[2][1] else opt3[1][1];
gw3: if nt3 then opt3[2][1] else opt3[3][1];
v4: plist[ix][2][4][2]; c4: plist[ix][2][4][1];
sm4: is(c4 = "same"); op4: is(c4 = "opp"); nt4: is(c4 = "not"); pr4: not nt4;
k4: v4[1]/A[1];
rt4: [v4[1]/A[1], v4[2]/A[2], v4[3]/A[3]];
opt4: [["same4", sm4, "parallel, same direction"], ["opp4", op4, "parallel, opposite direction"], ["not4", nt4, "not parallel"]];
ta4: first(mcq_correct(opt4));
/* named error: same and opposite confused; a near miss taken as parallel */
dg4: if sm4 then opt4[2][1] else opt4[1][1];
gw4: if nt4 then opt4[2][1] else opt4[3][1];
cats: [c1, c2, c3, c4];
